QQC2.CheckBox {
    id: appVolumeEnabled
    text: i18nc("@option:check", "Adjust hovered task's volume with mouse wheel")
}

QQC2.ComboBox {
    id: appVolumeModifier
    Kirigami.FormData.label: i18nc("@label:listbox", "Volume scroll modifier:")
    enabled: appVolumeEnabled.checked
    model: [
        i18nc("@item:inlistbox", "None"),
        i18nc("@item:inlistbox", "Alt"),
    ]
}

