WheelHandler {
    id: wheelHandler

    acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad

    property bool handleWheelEvents: true

    enabled: handleWheelEvents && Plasmoid.configuration.wheelEnabled !== 0

    onWheel: event => {
        // magic number 15 for common "one scroll"
        // See https://doc.qt.io/qt-6/qml-qtquick-wheelhandler.html#rotation-prop
        let increment = 0;
        while (rotation >= 15) {
            rotation -= 15;
            increment++;
        }
        while (rotation <= -15) {
            rotation += 15;
            increment--;
        }
        const anchor = dropArea.target.childAt(event.x, event.y);
        if (Plasmoid.configuration.wheelEnabled === 3) {
            const loudest = anchor?.audioStreams?.reduce((loudest, stream) => Math.max(loudest, stream.volume), 0)
            const step = (pulseAudio.item.normalVolume - pulseAudio.item.minimalVolume) * pulseAudio.item.globalConfig.volumeStep / 100;
            anchor?.audioStreams?.forEach((stream) => {
                let delta = step * increment;
                if (loudest > 0) {
                    delta *= stream.volume / loudest;
                }
                const volume = stream.volume + delta;
                console.log(volume, Math.max(pulseAudio.item.minimalVolume, Math.min(volume, pulseAudio.item.normalVolume)));
                stream.model.Volume = Math.max(pulseAudio.item.minimalVolume, Math.min(volume, pulseAudio.item.normalVolume));
                stream.model.Muted = volume === 0
            })
        return;
        }
        while (increment !== 0) {
            TaskManagerApplet.TaskTools.activateNextPrevTask(anchor, increment < 0, Plasmoid.configuration.wheelSkipMinimized, Plasmoid.configuration.wheelEnabled, tasks);
            increment += (increment < 0) ? 1 : -1;
        }
    }
}

contents/ui/MouseHandler.qml.new:
WheelHandler {
    id: wheelHandler

    acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad

    property bool handleWheelEvents: true
    property var appVolumeAcc: AppVolume.createAccumulator()

    enabled: handleWheelEvents && (Plasmoid.configuration.wheelEnabled !== 0 || Plasmoid.configuration.appVolumeEnabled)

    onWheel: event => {
        const anchor = isGroupDialog
            ? dropArea.target.itemAt(event.x, event.y)
            : dropArea.target.childAt(event.x, event.y);
        const streams = anchor?.audioStreams;
        const pa = pulseAudio.item;
        if (Plasmoid.configuration.appVolumeEnabled
                && pa
                && streams && streams.length > 0
                && AppVolume.modifierMatches(event.modifiers, Plasmoid.configuration.appVolumeModifier, Qt.AltModifier)) {
            const volSteps = AppVolume.consumeWheelSteps(appVolumeAcc, anchor, event.angleDelta.y, event.pixelDelta.y);
            if (volSteps !== 0) {
                AppVolume.applyVolumeSteps(streams, volSteps, pa.minimalVolume, pa.normalVolume, AppVolume.DEFAULT_STEP_PERCENT);
            }
            event.accepted = true;
            return;
        }

        if (Plasmoid.configuration.wheelEnabled === 0) {
            event.accepted = false;
            return;
        }

        // magic number 15 for common "one scroll"
        // See https://doc.qt.io/qt-6/qml-qtquick-wheelhandler.html#rotation-prop
        let increment = 0;
        while (rotation >= 15) {
            rotation -= 15;
            increment++;
        }
        while (rotation <= -15) {
            rotation += 15;
            increment--;
        }
        if (Plasmoid.configuration.wheelEnabled === 3) {
            if (pa && streams && streams.length > 0 && increment !== 0) {
                AppVolume.applyVolumeSteps(streams, increment, pa.minimalVolume, pa.normalVolume, AppVolume.DEFAULT_STEP_PERCENT);
            }
            return;
        }
        while (increment !== 0) {
            TaskManagerApplet.TaskTools.activateNextPrevTask(anchor, increment < 0, Plasmoid.configuration.wheelSkipMinimized, Plasmoid.configuration.wheelEnabled, tasks);
            increment += (increment < 0) ? 1 : -1;
        }
    }
}
